package br.com.agenciafenixwarriors.liveai;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.view.*;import android.widget.*;
public class OverlayService extends Service{private WindowManager wm;private View bubble;private int minutes=15,viewers=4,comments=2,followers=0,gifts=0,stars=0,pk=0;private long beans=0;@Override public void onCreate(){super.onCreate();createChannel();startForeground(4242,new Notification.Builder(this,"fenix_live_ai").setContentTitle("FÊNIX LIVE AI ativo").setContentText("Coach disponível sobre a BIGO").setSmallIcon(android.R.drawable.star_big_on).build());showBubble();}private void createChannel(){if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel("fenix_live_ai","FÊNIX LIVE AI",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(c);}}private TextView t(String s,int sp){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(sp);v.setPadding(18,12,18,12);return v;}private void showBubble(){wm=(WindowManager)getSystemService(WINDOW_SERVICE);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);GradientDrawable bg=new GradientDrawable();bg.setColor(0xEE111114);bg.setCornerRadius(28);bg.setStroke(2,0xFFE24A2A);box.setBackground(bg);TextView head=t("🐦‍🔥 FÊNIX",18);box.addView(head);TextView advice=t("Toque em COACH para estratégia.",14);box.addView(advice);Button coach=new Button(this);coach.setText("COACH");box.addView(coach);Button plusGift=new Button(this);plusGift.setText("+ Presente");box.addView(plusGift);Button close=new Button(this);close.setText("Fechar");box.addView(close);coach.setOnClickListener(v->{String a=CoachEngine.advise(minutes,viewers,beans,comments,followers,gifts,stars,pk);int sc=CoachEngine.score(minutes,viewers,beans,comments,followers,gifts);advice.setText("SCORE "+sc+"/100\n"+a);minutes+=3;});plusGift.setOnClickListener(v->{gifts++;beans+=100;advice.setText("Presente registrado. "+CoachEngine.advise(minutes,viewers,beans,comments,followers,gifts,stars,pk));});close.setOnClickListener(v->stopSelf());int type=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;WindowManager.LayoutParams lp=new WindowManager.LayoutParams(420,-2,type,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.END;lp.x=12;lp.y=240;head.setOnTouchListener(new View.OnTouchListener(){float x,y;int ox,oy;public boolean onTouch(View v,android.view.MotionEvent e){if(e.getAction()==0){x=e.getRawX();y=e.getRawY();ox=lp.x;oy=lp.y;return true;}if(e.getAction()==2){lp.x=ox-(int)(e.getRawX()-x);lp.y=oy+(int)(e.getRawY()-y);wm.updateViewLayout(box,lp);return true;}return false;}});bubble=box;wm.addView(bubble,lp);}@Override public void onDestroy(){if(bubble!=null&&wm!=null)wm.removeView(bubble);super.onDestroy();}@Override public android.os.IBinder onBind(Intent i){return null;}}
